  qty            int  not null default 1,
  frame_price    numeric(10,2),
  lens_package   text,
  lens_total     numeric(10,2),
  total          numeric(10,2),
  rx_data        jsonb,
  notified_at    timestamptz,  -- when abandoned cart message was sent
