-- >>> 0018_customer_self_access.sql
-- Website customers must be able to read/update their own customers row.
--
-- Migration 0001 only granted `org_id = public.current_org()`, which resolves
-- via the profiles table and is therefore NULL for non-staff website logins.
-- Every portal page calls getCustomer() -> `customers where auth_user_id =
-- auth.uid()`, and the customer-read policies on sales/prescriptions/
-- appointments/loyalty_ledger all depend on that same subquery — so without
-- this policy the whole /my/* portal bounced users back to /my/login.

create policy cust_self_select on customers
  for select to authenticated
  using (auth_user_id = auth.uid());

create policy cust_self_update on customers
  for update to authenticated
  using (auth_user_id = auth.uid())
  with check (auth_user_id = auth.uid());

comment on policy cust_self_select on customers is
  'A logged-in website customer can read their own profile row';

comment on policy cust_self_update on customers is
  'A logged-in website customer can edit their own profile row';


-- >>> 0019_customer_document_access.sql
-- ── Customer-readable document rows for the portal ────────────────────────────
-- Powers /my/documents and repairs the data visibility of the existing portal
-- pages (/my/orders, /my/payments, /my/prescriptions, /my/repairs …).
--
-- Why this is needed: every base SELECT policy on sales / sale_lines /
-- payments / prescriptions / repairs / appointments is
-- `org_id = public.current_org()`, and current_org() resolves via
-- `profiles … is_approved` — which is NULL for website customers (they have no
-- approved staff profile; see 0018). A NULL comparison silently returns zero
-- rows in PostgREST, so the portal queries succeed but always come back empty.
--
-- These policies grant SELECT on a customer's OWN rows only (keyed on
-- auth.uid() → customers.auth_user_id), and each one is created only when a
-- policy of the same name does not already exist — so this file is safe to run
-- on databases that were patched manually (it will simply no-op).

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'sales_customer_select') then
    create policy sales_customer_select on public.sales
      for select to authenticated
      using (customer_id in (select id from public.customers where auth_user_id = auth.uid()));
  end if;

  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'sale_lines_customer_select') then
    create policy sale_lines_customer_select on public.sale_lines
      for select to authenticated
      using (sale_id in (select id from public.sales
                         where customer_id in (select id from public.customers where auth_user_id = auth.uid())));
  end if;

  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'payments_customer_select') then
    create policy payments_customer_select on public.payments
      for select to authenticated
      using (sale_id in (select id from public.sales
                         where customer_id in (select id from public.customers where auth_user_id = auth.uid())));
  end if;

  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'prescriptions_customer_select') then
    create policy prescriptions_customer_select on public.prescriptions
      for select to authenticated
      using (customer_id in (select id from public.customers where auth_user_id = auth.uid()));
  end if;

  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'repairs_customer_select') then
    create policy repairs_customer_select on public.repairs
      for select to authenticated
      using (customer_id in (select id from public.customers where auth_user_id = auth.uid()));
  end if;

  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'appointments_customer_select') then
    create policy appointments_customer_select on public.appointments
      for select to authenticated
      using (customer_id in (select id from public.customers where auth_user_id = auth.uid()));
  end if;
end $$;

-- ── Prescription scans (private `prescriptions` bucket) ───────────────────────
-- Files are stored at <org_id>/<uuid>.jpg (see apps/erp/src/app/(app)/
-- prescriptions/view.tsx). The existing rx_files_read policy is org-scoped via
-- current_org(), which is NULL for customers — so let a customer read exactly
-- the objects attached to their own prescriptions (enables "View scan" on
-- /my/documents, which signs a short-lived URL server-side).
do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'storage' and policyname = 'rx_files_customer_read') then
    create policy rx_files_customer_read on storage.objects
      for select to authenticated
      using (bucket_id = 'prescriptions'
        and exists (select 1 from public.prescriptions p
                    where p.image_path = name
                      and p.customer_id in (select id from public.customers where auth_user_id = auth.uid())));
  end if;
end $$;


-- >>> 0020_display_shelf_repair_photos.sql
-- ── 0020: Display & shelf management + repair photos & consent ────────────────
--
-- Part 1 — products gain display / shelf placement columns (managed from the
--         ERP product drawer's new "Display" tab and the top-level
--         "Display & Shelf" inventory tab).
-- Part 2 — repairs gain intake photos (<=3, customer or staff), staff
--         after-repair photos (<=3), and a recorded customer consent for
--         registering WITHOUT any photo.
-- Part 3 — private `repair-images` bucket at <org_id>/<customer_id>/<uuid>.jpg
--         so BOTH staff (org folder) and the owning customer (own folder)
--         can read the same objects.
-- Part 4 — RLS: customer INSERT on repairs (own customer, own org, forced
--         pending/unpaid) and authenticated read of active branches (the
--         portal register form needs a branch list; branches_anon only
--         covers the anon role, so /my/repairs.branches(name) is null today).

-- ── Part 1: products display & shelf ──────────────────────────────────────────
alter table products
  add column if not exists on_display boolean not null default true,
  add column if not exists display_section text not null default 'shelf',
  add column if not exists shelf_location text,
  add column if not exists display_order int not null default 0;

do $$ begin
  if not exists (select 1 from pg_constraint
                 where conrelid = 'public.products'::regclass
                   and conname = 'products_display_section_check') then
    alter table public.products add constraint products_display_section_check
      check (display_section in ('window','counter','wall','shelf','back_store'));
  end if;
end $$;

-- ── Part 2: repairs photos + consent ──────────────────────────────────────────
alter table repairs
  add column if not exists images text[] not null default '{}',
  add column if not exists after_images text[] not null default '{}',
  add column if not exists photo_consent boolean not null default false,
  add column if not exists photo_consent_at timestamptz;

-- ── Part 3: repair-images bucket + object policies ────────────────────────────
insert into storage.buckets (id, name, public)
  values ('repair-images', 'repair-images', false)
  on conflict do nothing;

do $$
begin
  -- Staff: any object under their own org folder (read + write).
  if not exists (select 1 from pg_policies where schemaname = 'storage' and policyname = 'repair_files_staff_read') then
    create policy repair_files_staff_read on storage.objects
      for select to authenticated
      using (bucket_id = 'repair-images'
        and (storage.foldername(name))[1] = public.current_org()::text);
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and policyname = 'repair_files_staff_write') then
    create policy repair_files_staff_write on storage.objects
      for insert to authenticated
      with check (bucket_id = 'repair-images'
        and (storage.foldername(name))[1] = public.current_org()::text);
  end if;

  -- Customer: only objects under <their org>/< their customer id >/…
  -- (covers both their own uploads and staff uploads placed in their folder).
  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'repair_files_customer_read') then
    create policy repair_files_customer_read on storage.objects
      for select to authenticated
      using (bucket_id = 'repair-images'
        and exists (select 1 from public.customers c
                    where c.auth_user_id = auth.uid()
                      and (storage.foldername(name))[1] = c.org_id::text
                      and (storage.foldername(name))[2] = c.id::text));
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and policyname = 'repair_files_customer_write') then
    create policy repair_files_customer_write on storage.objects
      for insert to authenticated
      with check (bucket_id = 'repair-images'
        and exists (select 1 from public.customers c
                    where c.auth_user_id = auth.uid()
                      and (storage.foldername(name))[1] = c.org_id::text
                      and (storage.foldername(name))[2] = c.id::text));
  end if;
end $$;

-- ── Part 4: portal RLS ────────────────────────────────────────────────────────
-- Customers can register a repair themselves. Tightened so they cannot forge
-- status/payment/ownership: pending + unpaid + own customer + own org; the
-- repairs_before trigger recomputes total_amount regardless of any input.
do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'repairs_customer_insert') then
    create policy repairs_customer_insert on public.repairs
      for insert to authenticated
      with check (
        status = 'pending'
        and paid = false
        and sale_id is null
        and (customer_id, org_id) in
            (select id, org_id from public.customers where auth_user_id = auth.uid()));
  end if;

  -- Branch picker for the register form (and fixes branches(name) on
  -- /my/repairs, which is null today because branches_anon targets only anon).
  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'branches_active_read') then
    create policy branches_active_read on public.branches
      for select to authenticated using (is_active);
  end if;
end $$;


-- >>> 0021_sale_rx_lifecycle.sql
-- ── 0021: POS prescription hard-copy gate + sale lifecycle events ─────────────
--
-- Part 1 — sales gain the staff consent attestation used when an order is
--         confirmed WITHOUT a prescription hard copy (the image itself lives
--         on prescriptions.image_path in the private `prescriptions` bucket,
--         already linked via sales.prescription_id / rx_snapshot).
-- Part 2 — prescriptions.source gains 'external' (prescriptions written by an
--         outside practice) + external_practice names the practice.
-- Part 3 — sale_events: customer-visible status history for orders, written
--         by triggers on sales so every lifecycle path is covered
--         (place_sale, advance_lab_orders, deliver_order, cancel_order,
--         markSent, quotation conversion) without touching those functions.
--         Mirrors repair_events (0008) but org_id is copied from the sale row
--         (NOT current_org()) so events also land for web/anon checkouts.
-- Part 4 — RLS: staff org read + customer read of THEIR OWN sale's events,
--         and customer read of their own repair_events (portal timeline on
--         /my/repairs/[id]).

-- ── Part 1: sales consent columns ─────────────────────────────────────────────
alter table sales
  add column if not exists rx_consent boolean not null default false,
  add column if not exists rx_consent_at timestamptz;

-- ── Part 2: external-practice prescriptions ───────────────────────────────────
alter table prescriptions
  add column if not exists external_practice text;

do $$ declare c record; begin
  -- Drop any existing check constraint that validates `source` (auto-named
  -- prescriptions_source_check, or a differently-named manual one), then
  -- re-add with 'external' included.
  for c in
    select conname from pg_constraint
    where conrelid = 'public.prescriptions'::regclass
      and contype = 'c'
      and pg_get_constraintdef(oid) ilike '%source%'
  loop
    execute format('alter table public.prescriptions drop constraint %I', c.conname);
  end loop;
  alter table public.prescriptions add constraint prescriptions_source_check
    check (source in ('manual','ocr','external'));
end $$;

-- ── Part 3: sale_events + triggers ────────────────────────────────────────────
create table if not exists sale_events (
  id bigserial primary key,
  org_id uuid not null references organizations(id),
  sale_id uuid not null references sales(id) on delete cascade,
  from_status text, to_status text not null,
  note text, by_user uuid default auth.uid(), at timestamptz default now());

create index if not exists idx_sale_events_sale on sale_events (sale_id, at);

create or replace function public.sale_events_track() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    insert into sale_events (org_id, sale_id, from_status, to_status, note)
    values (new.org_id, new.id, null, new.status,
            case when new.kind = 'quotation' then 'Quotation created'
                 else 'Order placed' end);
  elsif new.status is distinct from old.status then
    insert into sale_events (org_id, sale_id, from_status, to_status, note)
    values (new.org_id, new.id, old.status, new.status, null);
  end if;
  return new;
end $$;

do $$ begin
  if not exists (select 1 from pg_trigger
                 where tgrelid = 'public.sales'::regclass
                   and tgname = 'trg_sales_events') then
    create trigger trg_sales_events
      after insert or update on public.sales
      for each row execute function public.sale_events_track();
  end if;
end $$;

-- ── Part 4: RLS ───────────────────────────────────────────────────────────────
alter table sale_events enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'sale_events_staff_select') then
    create policy sale_events_staff_select on public.sale_events
      for select using (org_id = public.current_org());
  end if;

  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'sale_events_customer_select') then
    create policy sale_events_customer_select on public.sale_events
      for select to authenticated
      using (sale_id in (select id from public.sales
                         where customer_id in (select id from public.customers
                                               where auth_user_id = auth.uid())));
  end if;

  -- Portal repair timeline: customers can read the event history of their own
  -- repairs (base policy from 0008 is org-scoped = NULL for customers).
  if not exists (select 1 from pg_policies where schemaname = 'public' and policyname = 'repair_events_customer_select') then
    create policy repair_events_customer_select on public.repair_events
      for select to authenticated
      using (repair_id in (select id from public.repairs
                           where customer_id in (select id from public.customers
                                                 where auth_user_id = auth.uid())));
  end if;
end $$;

